<?php
require_once __DIR__ . '/../config/auth.php';
require_admin();
function mn_e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function mn_rupiah($v): string { return 'Rp' . number_format((float)$v, 0, ',', '.'); }
$today = date('Y-m-d');
$values = [
 'customer_name'=>trim((string)($_POST['customer_name'] ?? '')),
 'customer_phone'=>trim((string)($_POST['customer_phone'] ?? '')),
 'customer_address'=>trim((string)($_POST['customer_address'] ?? '')),
 'invoice_date'=>trim((string)($_POST['invoice_date'] ?? $today)),
 'notes'=>trim((string)($_POST['notes'] ?? '')),
 'discount'=>max(0,(float)($_POST['discount'] ?? 0)),
 'paid'=>max(0,(float)($_POST['paid'] ?? 0)),
];
$names = $_POST['item_name'] ?? [];
$qtys = $_POST['item_qty'] ?? [];
$prices = $_POST['item_price'] ?? [];
$items = [];
if (is_array($names)) foreach ($names as $i=>$name) {
 $name = trim((string)$name); $qty = isset($qtys[$i]) ? max(0,(float)$qtys[$i]) : 0; $price = isset($prices[$i]) ? max(0,(float)$prices[$i]) : 0;
 if ($name !== '' && $qty > 0) $items[] = ['name'=>$name,'qty'=>$qty,'price'=>$price,'subtotal'=>$qty*$price];
}
$submitted = $_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['make_invoice']);
$error = '';
if ($submitted && ($values['customer_name']==='' || !$items)) $error = 'Nama pelanggan dan minimal satu produk wajib diisi.';
if ($submitted && !$error) {
 $subtotal = array_sum(array_column($items,'subtotal'));
 $discount = min($values['discount'], $subtotal);
 $total = max(0, $subtotal-$discount);
 $paid = min($values['paid'], $total);
 $invoiceNo = 'RIP-M-' . date('Ymd') . '-' . strtoupper(substr(bin2hex(random_bytes(3)),0,6));
 $dateLabel = date('d F Y', strtotime($values['invoice_date'] ?: $today));
 $dateLabel = strtr($dateLabel, ['January'=>'Januari','February'=>'Februari','March'=>'Maret','April'=>'April','May'=>'Mei','June'=>'Juni','July'=>'Juli','August'=>'Agustus','September'=>'September','October'=>'Oktober','November'=>'November','December'=>'Desember']);
 $status = $paid >= $total ? 'LUNAS' : ($paid > 0 ? 'DP / SEBAGIAN' : 'BELUM BAYAR');
 ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nota Manual <?php echo mn_e($invoiceNo); ?></title><style>
