<script>
(()=>{const rows=document.getElementById('itemRows');document.getElementById('addItem').addEventListener('click',()=>{const tr=document.createElement('tr');tr.innerHTML='<td><input name="item_name[]" required placeholder="Nama produk / jasa" style="width:100%;padding:10px;border:1px solid #eadde3;border-radius:8px"></td><td><input name="item_qty[]" required type="number" min="0.01" step="0.01" value="1" style="width:100%;padding:10px;border:1px solid #eadde3;border-radius:8px"></td><td><input name="item_price[]" required type="number" min="0" step="1" placeholder="Harga satuan" style="width:100%;padding:10px;border:1px solid #eadde3;border-radius:8px"></td><td><button type="button" class="admin-btn danger removeItem">Hapus</button></td>';rows.appendChild(tr)});rows.addEventListener('click',e=>{const b=e.target.closest('.removeItem');if(!b)return;if(rows.querySelectorAll('tr').length>1)b.closest('tr').remove();else b.closest('tr').querySelectorAll('input').forEach(i=>{if(i.name==='item_qty[]')i.value='1';else i.value=''})})})();
</script>
